# Meeting 3, part 3 (moved from meeting 2): a full exercise from the identity table to both statements, in very gradual stages.
# Omer's lab (a service company, founded 1.1.2027): cash 100,200, customers 5,000, parts 4,000, equipment 45,000; suppliers 8,000,
# loan 40,000; share capital 10,000, premium 50,000; revenue 150,000, expenses 103,800 (operating 88,000, interest 2,000, tax 13,800 =
# 23% of 60,000), net profit 46,200. Total assets 154,200 = liabilities 48,000 + equity 106,200.

A3 = [('cash', 'מזומן', 'a'), ('cust', 'לקוחות', 'a'), ('inv', 'מלאי חלקים', 'a'), ('ppe', 'ציוד', 'a'), ('sup', 'ספקים', 'l'), ('loan', 'הלוואה', 'l'),
      ('sc', 'הון מניות', 'e'), ('prem', 'פרמיה', 'e'), ('rev', 'הכנסות', 'pl'), ('exp', 'הוצאות (מינוס)', 'pl')]
OEV = ['א. ב-1.1.2027 הוקמה מעבדת התיקונים של עומר בע״מ. החברה הנפיקה 10,000 מניות בנות 1 ש״ח ערך נקוב כל אחת, תמורת 60,000 ש״ח במזומן.',
       'ב. החברה לוותה מהבנק 40,000 ש״ח, לפירעון בעוד שלוש שנים.',
       'ג. החברה קנתה ציוד תיקונים, מלחמים ומיקרוסקופ, ב-45,000 ש״ח. 25,000 ש״ח שולמו במזומן, והיתרה תשולם לספק בעוד חודשיים.',
       'ד. החברה קנתה מלאי חלקי חילוף, מסכים וסוללות, ב-18,000 ש״ח, ושילמה במזומן.',
       'ה. במהלך השנה ביצעה החברה תיקונים בשווי 150,000 ש״ח. 130,000 ש״ח התקבלו במזומן, והיתרה תתקבל מלקוחות עסקיים בהמשך.',
       'ו. בתיקונים נעשה שימוש בחלקי חילוף שעלותם 14,000 ש״ח.',
       'ז. החברה שילמה במזומן שכר לטכנאים: 50,000 ש״ח.',
       'ח. החברה שילמה במזומן שכר דירה למעבדה: 24,000 ש״ח.',
       'ט. הלקוחות העסקיים שילמו 15,000 ש״ח מתוך החוב שלהם.',
       'י. החברה שילמה לספק הציוד 12,000 ש״ח מתוך החוב.',
       'יא. החברה שילמה לבנק ריבית על ההלוואה: 2,000 ש״ח.',
       'יב. החברה שילמה מס הכנסה: 13,800 ש״ח.']
OMER = [
 ('א. הנפקת מניות', {'cash': (60000, 'הכסף שהתקבל.'), 'sc': (10000, '10,000 מניות כפול 1 ש״ח ערך נקוב.'), 'prem': (50000, 'מה ששולם מעבר לערך הנקוב: 60,000 פחות 10,000.')}),
 ('ב. הלוואה מהבנק', {'cash': (40000, 'הכסף שהתקבל.'), 'loan': (40000, 'חוב לבנק.')}),
 ('ג. ציוד, חלק באשראי', {'cash': (-25000, 'מה ששולם עכשיו.'), 'ppe': (45000, 'כל עלות הציוד, גם החלק שעוד לא שולם.'), 'sup': (20000, 'היתרה: 45,000 פחות 25,000.')}),
 ('ד. מלאי חלקים במזומן', {'cash': (-18000, 'הכסף יצא.'), 'inv': (18000, 'חלקים במחסן: נכס.')}),
 ('ה. תיקונים', {'cash': (130000, 'מה שהתקבל.'), 'cust': (20000, 'מה שעוד יתקבל: 150,000 פחות 130,000.'), 'rev': (150000, 'כל שווי התיקונים.')}),
 ('ו. חלקים שנצרכו', {'inv': (-14000, 'החלקים יצאו מהמחסן.'), 'exp': (-14000, 'המשאב נצרך: הוצאה.')}),
 ('ז. שכר טכנאים', {'cash': (-50000, 'הכסף יצא.'), 'exp': (-50000, 'הוצאת שכר.')}),
 ('ח. שכר דירה', {'cash': (-24000, 'הכסף יצא.'), 'exp': (-24000, 'הוצאת שכר דירה.')}),
 ('ט. גבייה מלקוחות', {'cash': (15000, 'הכסף נכנס.'), 'cust': (-15000, 'הלקוחות חייבים פחות. אין הכנסה חדשה.')}),
 ('י. תשלום לספק הציוד', {'cash': (-12000, 'הכסף יצא.'), 'sup': (-12000, 'החוב לספק קטן. אין הוצאה.')}),
 ('יא. ריבית', {'cash': (-2000, 'הכסף יצא.'), 'exp': (-2000, 'הוצאות מימון.')}),
 ('יב. מס הכנסה', {'cash': (-13800, 'הכסף יצא.'), 'exp': (-13800, 'מסים על ההכנסה.')})]
_chk = {}
for _lab, _e in OMER:
    for _k, _v in _e.items(): _chk[_k] = _chk.get(_k, 0) + _v[0]
assert _chk == {'cash': 100200, 'cust': 5000, 'inv': 4000, 'ppe': 45000, 'sup': 8000, 'loan': 40000, 'sc': 10000, 'prem': 50000, 'rev': 150000, 'exp': -103800}, _chk
assert round(0.23 * (150000 - 14000 - 50000 - 24000 - 2000)) == 13800

# ================================================================ part 6
opener(3, 'תרגיל מלא, מהזהות ועד הדוחות: מעבדת התיקונים של עומר', 'שאלת החלק: האם אפשר לעשות לבד את כל הדרך, מהעסקאות ועד שני הדוחות?',
       ['השאלה המלאה', 'שלב 1: עסקאות שנוגעות רק במאזן', 'שלב 2: הכנסות והוצאות', 'שלב 3: גבייה, תשלומים, ריבית ומס', 'שלב 4: סיכום העמודות', 'שלב 5: דוח רווח והפסד של חברת שירות', 'שלב 6: המאזן', 'מה למדנו מהתרגיל'], 30)

S('s-omer', 'השאלה המלאה', 'מעבדת התיקונים של עומר בע״מ: השאלה המלאה',
  '<div class="card qstem omerq"><div class="oq2">' + ''.join(f'<p>{TX(x)}</p>' for x in OEV) + '</div>'
  + '<p class="req">' + TX('<b>נדרש:</b> רשמו את כל העסקאות בטבלת הזהות החשבונאית, סכמו כל עמודה, וערכו דוח רווח והפסד לשנת 2027 ומאזן ליום 31.12.2027. שיעור המס 23%.') + '</p></div>'
  + BAND('dg', 'נסו לבד, שלב אחר שלב. בכל שלב העסקאות שלו כתובות שוב ליד הגיליון, ו״הצעד הבא״ פותר תא אחד בכל לחיצה, עם הסבר.', 1), kick='חלק 6 · נסו לבד')

_otask = 'רשמו כל עסקה בשורה שלה: השינוי בעמודה של כל חשבון, בפלוס כשהוא גדל ובמינוס כשהוא קטן. הבקרה בעמודה האחרונה צריכה להראות מקף, כלומר 0.'
QT('x-o1', 'שלב 1', 'עסקאות א עד ד: רק המאזן (מזומן, ציוד, ספקים, הון מניות, פרמיה)', OEV[:4], _otask, IDSHEET(A3, OMER[:4], [0, 1, 2, 3], date='31.12.2027'),
   note=[('dg', '<b>מה למדנו בשלב 1:</b> הנפקה מעל הערך הנקוב מתחלקת לשניים: הון מניות 10,000 ופרמיה 50,000. קנייה שחלקה באשראי נוגעת בשלושה חשבונות באותה שורה: ציוד, מזומן וספקים.', 1)],
   more=MORE('למה הציוד נרשם ב-45,000 ולא ב-25,000?', ['הנכס הוא כל הציוד שהחברה קיבלה, לא רק החלק ששולם. 25,000 יצאו מהמזומן, ו-20,000 הם חוב לספק. בצד השני: התחייבות של 20,000.', 'בדיקה: נכסים: ציוד 45,000 פחות מזומן 25,000 = 20,000. התחייבויות: 20,000. הבקרה 0.']),
   done='ארבע השורות מאוזנות.')
QT('x-o2', 'שלב 2', 'עסקאות ה עד ח: הכנסות והוצאות (מזומן, לקוחות, מלאי, הכנסות, הוצאות)', OEV[4:8], _otask, IDSHEET(A3, OMER[:8], [4, 5, 6, 7], date='31.12.2027'),
   note=[('dg', '<b>מה למדנו בשלב 2:</b> ההכנסה היא כל שווי התיקונים, 150,000, גם מה שעוד לא התקבל. חלקים שנצרכו הופכים מנכס להוצאה, בלי שיצא שקל באותו רגע.', 1)],
   more=MORE('למה עסקה ו לא נוגעת במזומן?', ['את החלקים כבר קנו ושילמו בעסקה ד. בעסקה ו הם רק נצרכו: מלאי קטן, והוצאה נרשמת.', 'מזומן והוצאה הם שני דברים שונים: אחד אומר מתי שילמו, והשני מתי נצרך המשאב.']),
   done='עוד ארבע שורות מאוזנות.')
QT('x-o3', 'שלב 3', 'עסקאות ט עד יב: גבייה, תשלום לספק, ריבית ומס', OEV[8:], _otask, IDSHEET(A3, OMER, [8, 9, 10, 11], date='31.12.2027'),
   note=[('dg', '<b>מה למדנו בשלב 3:</b> גבייה מלקוחות ותשלום לספק רק מחליפים נכס בנכס, או מקטינים נכס וחוב יחד: הם לא הכנסה ולא הוצאה. ריבית ומס הם הוצאות.', 1)],
   more=MORE('איך יודעים אם משהו הוא הכנסה או הוצאה?', ['שואלים: האם ההון העצמי של הבעלים השתנה? בגבייה החברה לא התעשרה: הכסף כבר היה שלה כחוב של הלקוח.', 'בריבית החברה נעשתה ענייה יותר ב-2,000: זו הוצאה.']),
   done='כל 12 השורות מאוזנות.')
QT('x-o4', 'שלב 4', 'סיכום העמודות והרווח הנקי', ['כל 12 העסקאות של עומר רשומות בטבלה.', '<b>נדרש:</b> סכמו כל עמודה, בדקו שהבקרה 0, וחשבו את הרווח הנקי.'],
   'בשורת הסיכום: SUM לכל עמודה. בשורה שמתחתיה: הכנסות ועוד הוצאות.', IDSHEET(A3, OMER, [], total=True, profit=True, date='31.12.2027'),
   note=[('dg', '<b>מה למדנו בשלב 4:</b> מזומן 100,200, אבל רווח נקי 46,200. רווח אינו מזומן: חלק מהמזומן בא מהבעלים ומהבנק, וחלק מהרווח עוד אצל הלקוחות.', 1)],
   hints=['בכל עמודה: =SUM מהשורה של א ועד השורה של יב.', 'רווח נקי: סכום ההכנסות ועוד סכום ההוצאות, שכבר במינוס.'], remind='=SUM(B3:B14)', done='הבקרה 0, ורווח נקי 46,200.')

_ois = [('הכנסות מתיקונים', 150000), ('חלקי חילוף שנצרכו', -14000), ('שכר טכנאים', -50000), ('שכר דירה', -24000), ('ריבית (מימון)', -2000), ('מס הכנסה', -13800)]
_oil = [('הכנסות מתיקונים', '=B2', 'מעמודת ההכנסות.', 0), ('הוצאות תפעוליות', '=B3+B4+B5', 'חלקים, שכר ושכר דירה: כל ההוצאות חוץ ממימון ומס.', 0), ('רווח תפעולי', '=E2+E3', '', 1),
        ('הוצאות מימון', '=B6', 'הריבית.', 0), ('רווח לפני מסים על ההכנסה', '=E4+E5', '', 1), ('מסים על ההכנסה', '=B7', '23% מ-60,000.', 0), ('רווח נקי', '=E6+E7', 'השורה התחתונה.', 1)]
QT('x-o5', 'שלב 5', 'דוח רווח והפסד של חברת שירות', ['מימין: השורות של עמודות ההכנסות וההוצאות מהטבלה של עומר.',
   '<b>נדרש:</b> ערכו את דוח רווח והפסד של המעבדה לשנת 2027. זו חברת שירות: היא לא קונה ומוכרת סחורה.'],
   'בעמודה E: כל שורה בנוסחה, כמו בקפה נועה.', ISSHEET(_ois, _oil, 'עומר: דוח רווח והפסד 2027'),
   note=[('dg', '<b>מה למדנו בשלב 5:</b> בחברת שירות אין עלות מכר ורווח גולמי: ההכנסות, פחות כל ההוצאות התפעוליות יחד, נותנות את הרווח התפעולי.', 1)],
   hints=['הוצאות תפעוליות: =B3+B4+B5. רווח תפעולי: =E2+E3.'], remind='=E2+E3', done='רווח נקי 46,200, כמו בטבלה.')

_obal = [('מזומן', 100200), ('לקוחות', 5000), ('מלאי חלקים', 4000), ('ציוד', 45000), ('ספקים', 8000), ('הלוואה', 40000), ('הון מניות', 10000), ('פרמיה', 50000), ('הכנסות', 150000), ('הוצאות', -103800)]
_d, _g, _f, _s = BSSHEET(_obal, '')
_d.update({'D2': 'נכסים שוטפים', 'D3': 'מזומן', 'D4': 'לקוחות', 'D5': 'מלאי חלקים', 'D6': 'סך נכסים שוטפים', 'D7': 'נכסים לא שוטפים', 'D8': 'ציוד', 'D9': 'סך הנכסים',
           'F2': 'התחייבויות שוטפות', 'F3': 'ספקים', 'F4': 'התחייבויות לא שוטפות', 'F5': 'הלוואה', 'F6': 'סך ההתחייבויות', 'F7': 'הון עצמי', 'F8': 'הון מניות', 'F9': 'פרמיה',
           'F10': 'עודפים', 'F11': 'סך הון עצמי', 'F12': 'סך התחייבויות והון'})
_obs = [('E3', '=B2', 'מזומן.'), ('E4', '=B3', 'לקוחות: יתקבל בקרוב.'), ('E5', '=B4', 'מלאי החלקים שנשאר.'), ('E6', '=SUM(E3:E5)', 'סך הנכסים השוטפים.'), ('E8', '=B5', 'ציוד: משרת שנים.'), ('E9', '=E6+E8', 'סך הנכסים.'),
        ('G3', '=B6', 'ספקים: ייפרע בעוד חודשיים.'), ('G5', '=B7', 'הלוואה: בעוד שלוש שנים.'), ('G6', '=G3+G5', 'סך ההתחייבויות.'), ('G8', '=B8', 'הון מניות.'), ('G9', '=B9', 'פרמיה: גם היא הון עצמי.'),
        ('G10', '=B10+B11', 'עודפים: הרווח הנקי, 46,200.'), ('G11', '=SUM(G8:G10)', 'סך ההון העצמי.'), ('G12', '=G6+G11', 'שווה לסך הנכסים.')]
for _a in ['D6', 'D9', 'F6', 'F11', 'F12', 'E6', 'E9', 'G6', 'G11', 'G12']: _s[_a] = {'b': True, 'fill': '#f3f2f1'}
for _a in ['D2', 'D7', 'F2', 'F4', 'F7']: _s[_a] = {'b': True}
