QT('x-o6', 'שלב 6', 'המאזן ליום 31.12.2027', ['מימין: היתרות מהטבלה של עומר.', '<b>נדרש:</b> ערכו את הדוח על המצב הכספי של המעבדה ליום 31.12.2027.'],
   'נכסים בעמודה E, התחייבויות והון עצמי בעמודה G. עודפים: הכנסות ועוד הוצאות.',
   STSHEET(_d, _g, {a: f for a, f, _ in _obs}, [dict(cells={a: f}, note=f'{XL(f)}: {n}', sel=a) for a, f, n in _obs], [150, 95, 22, 175, 100, 190, 100], _f, _s),
   note=[('dg', '<b>מה למדנו בשלב 6:</b> בהון העצמי שלוש שורות: הון מניות, פרמיה ועודפים. שתיים מהבעלים, ואחת מהרווח. 154,200 בשני הצדדים.', 1)],
   hints=['עודפים: =B10+B11. סך הון עצמי: =SUM(G8:G10).', 'סך הצד השני: =G6+G11.'], remind='=G6+G11', done='154,200 = 154,200.')

